// Configuration file for the application
const config = {
  // Backend API configuration
  backend: {
    baseURL: process.env.REACT_APP_BACKEND_URL || 'http://localhost:4000',
    apiPath: '/api',
    uploadsPath: '/uploads'
  },

  // Frontend configuration
  frontend: {
    baseURL: process.env.REACT_APP_FRONTEND_URL || 'http://localhost:3000'
  }
};

// Helper functions for common URL operations
export const getApiUrl = (endpoint = '') => {
  return `${config.backend.baseURL}${config.backend.apiPath}${endpoint}`;
};

export const getUploadsUrl = (filename = '') => {
  return `${config.backend.baseURL}${config.backend.uploadsPath}/${filename}`;
};

export const getBackendUrl = (path = '') => {
  return `${config.backend.baseURL}${path}`;
};

export default config;
